<script setup lang="ts">
definePageMeta({middleware:'admin'})
const db=useSupabaseClient(),schools=ref<any[]>([]),rows=ref<any[]>([]),schoolId=ref(''),userId=ref(''),role=ref('teacher'),error=ref(''),success=ref('')
async function load(){const [s,m]=await Promise.all([db.from('schools').select('id,name').order('name'),db.from('school_memberships').select('school_id,user_id,role')]);schools.value=s.data||[];rows.value=m.data||[];if(!schoolId.value&&schools.value.length)schoolId.value=schools.value[0].id;error.value=s.error?.message||m.error?.message||''}
onMounted(load)
async function add(){error.value='';success.value='';const r=await db.from('school_memberships').upsert({school_id:schoolId.value,user_id:userId.value.trim(),role:role.value},{onConflict:'school_id,user_id'});if(r.error)error.value=r.error.message;else{success.value='Membership saved';userId.value='';await load()}}
</script>
<template><div class="page"><div class="shell admin-section"><NuxtLink to="/dashboard">← Dashboard</NuxtLink><h1>School Staff</h1><p>Staff must first have an account in Supabase Authentication. Enter their Auth User UUID to assign a school role.</p><form class="card editor" @submit.prevent="add"><label>School<select v-model="schoolId" required><option v-for="s in schools" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Auth user UUID<input v-model="userId" required placeholder="UUID"></label><label>Role<select v-model="role"><option value="teacher">Teacher</option><option value="school_admin">School Administrator</option></select></label><button class="btn">Assign Staff</button></form><p v-if="error" class="error">{{error}}</p><p v-if="success" class="success">{{success}}</p><div class="card"><h2>School Memberships</h2><div v-for="m in rows.filter(x=>x.school_id===schoolId)" :key="m.user_id" class="data-row"><span>{{m.user_id}}</span><small>{{m.role}}</small></div></div></div></div></template>
